catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading) return;

    // If cleared, remove messages and exit
    if (!newValue) {
        g_form.hideFieldMsg('new_return_date', true);
        g_form.clearMessages();
        return;
    }

    // Compare as dates (no time)
    var today = new Date();
    today.setHours(0, 0, 0, 0); // today @ 00:00
    var selected = new Date(newValue + 'T00:00:00'); // field is yyyy-MM-dd

    if (selected < today) {
        // Top banner + inline message + auto-scroll to the field
        g_form.addErrorMessage('New Return Date cannot be before today.');
        g_form.showFieldMsg('new_return_date', 'New Return Date cannot be before today.', 'error', true);
        // Clear invalid input
        g_form.setValue('new_return_date', '');
        return;
    } else {
        g_form.hideFieldMsg('new_return_date', true);
        g_form.clearMessages();
    }
}
